import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';

import { CourseMaterialsPage } from './course-materials.page';

const routes: Routes = [
  {
    path: '',
    component: CourseMaterialsPage
  },
  {
    path: 'course-details',
    loadChildren: () => import('./course-details/course-details.module').then( m => m.CourseDetailsPageModule)
  }
];

@NgModule({
  imports: [RouterModule.forChild(routes)],
  exports: [RouterModule],
})
export class CourseMaterialsPageRoutingModule {}
